files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #1a6ee0;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #FFFFFF;
  --vt-accent-on-deep: #aad0ff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
  scroll-behavior: smooth;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  background: var(--vt-surface-2);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  z-index: 1000;
  padding: 20px 0;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 15px;
}

.logo {
  text-decoration: none;
}

.brand {
  display: inline-block;
  color: var(--vt-accent);
  font-weight: 700;
  font-size: 24px;
}

.navLinks {
  display: flex;
  gap: 30px;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  text-decoration: none;
  padding: 10px 0;
  transition: color 0.3s;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

.hero {
  position: relative;
  overflow: hidden;
  height: 580px;
  margin-top: 94px;
}

.heroSlider {
  position: absolute;
  inset: 0;
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.slide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

.slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 50%;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  z-index: 2;
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.1);
}

.heroText h1 {
  font-size: 48px;
  font-weight: 700;
  margin: 0 0 10px;
  color: var(--vt-ink);
  line-height: 1.2;
}

.heroText p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  line-height: 1.6;
  margin-bottom: 1rem;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
}

.customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--vt-line);
  color: var(--vt-accent);
  text-align: center;
  transition: top 300ms cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin: 0;
  display: flex;
  align-items: center;
}

.phoneIcon::before {
  content: "\260E";
  margin-right: 8px;
  color: var(--vt-accent);
}

.section {
  padding: 7rem 0;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  width: 100%;
}

.aboutRow {
  display: flex;
  justify-content: center;
}

.aboutContent {
  max-width: 800px;
  text-align: center;
}

.aboutContent h2 {
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--vt-ink);
}

.aboutContent p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  line-height: 1.8;
  margin-bottom: 1rem;
}

.gallerySection {
  background: var(--vt-surface);
}

.galleryRow {
  display: flex;
}

.galleryItem {
  flex: 0 0 50%;
}

.galleryItem img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.timelineSection {
  padding-bottom: 0;
}

.sectionTitle {
  text-align: center;
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 4rem;
  color: var(--vt-ink);
}

.timeline {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  border-left: 1px solid var(--vt-line);
  transform: translateX(-50%);
}

.timelineNode {
  display: grid;
  grid-template-columns: 1fr 80px 1fr;
  column-gap: 30px;
  align-items: start;
  margin: 2rem 0;
  position: relative;
}

.timelineIcon {
  grid-column: 2;
  grid-row: 1;
  justify-self: center;
  align-self: start;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  font-weight: 700;
  color: var(--vt-accent);
  z-index: 2;
}

.timelineContent {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0.25rem;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
  font-size: 26px;
  font-weight: 600;
}

.timelineContent p {
  padding: 10px 30px;
  color: var(--vt-ink-soft);
  margin: 0;
}

.timelineDate {
  padding: 1rem 0;
  color: var(--vt-ink-soft);
  font-size: 16px;
}

.price {
  display: block;
  margin-top: 4px;
  color: var(--vt-accent);
  font-weight: 600;
}

.odd .timelineContent {
  grid-column: 1;
  text-align: right;
}

.odd .timelineDate {
  grid-column: 3;
  text-align: left;
}

.odd .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.even .timelineContent {
  grid-column: 3;
  text-align: left;
}

.even .timelineDate {
  grid-column: 1;
  text-align: right;
}

.even .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.footer {
  background: var(--vt-surface-2);
  padding: 5rem 0 3rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 30px;
}

.footerColHours,
.footerColContact,
.footerColSocial,
.footerColCopyright {
  flex: 1 1 200px;
}

.footer h5 {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 1.5rem;
  color: var(--vt-ink);
}

.footer p,
.footer ul {
  color: var(--vt-ink-soft);
  line-height: 1.6;
}

.footer a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s;
}

.footer a:hover {
  color: var(--vt-accent);
}

.socialLinks {
  display: flex;
  gap: 15px;
  list-style: none;
  padding: 0;
  margin: 0;
}

.copyright {
  font-size: 14px;
  color: var(--vt-ink-soft);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

@media (max-width: 991px) {
  .hero {
    height: auto;
    margin-top: 74px;
  }

  .heroSlider {
    position: relative;
    height: 400px;
  }

  .heroText {
    position: static;
    width: 100%;
    padding: 2rem;
  }

  .section {
    padding: 5rem 0;
  }

  .timelineNode {
    grid-template-columns: 1fr 60px 1fr;
    column-gap: 15px;
  }

  .timelineIcon {
    width: 60px;
    height: 60px;
    font-size: 24px;
  }
}

@media (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .heroText h1 {
    font-size: 38px;
  }

  .timeline::before {
    left: 30px;
    transform: none;
  }

  .timelineNode {
    display: flex;
    flex-direction: column;
    position: relative;
    padding-left: 60px;
  }

  .timelineIcon {
    position: absolute;
    left: 0;
    top: 0;
    width: 50px;
    height: 50px;
    font-size: 20px;
  }

  .timelineContent,
  .timelineDate {
    margin-left: 0;
    text-align: left !important;
  }

  .timelineContent h3::after {
    display: none;
  }

  .odd .timelineContent,
  .even .timelineContent {
    grid-column: auto;
  }

  .odd .timelineDate,
  .even .timelineDate {
    grid-column: auto;
    text-align: left !important;
  }

  .footerRow {
    flex-direction: column;
  }
}

@media (max-width: 480px) {
  .heroSlider {
    height: 300px;
  }

  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 20px;
  }

  .contactPhone {
    font-size: 12px;
  }

  .galleryRow {
    flex-direction: column;
  }

  .galleryItem {
    flex: 0 0 100%;
  }
}
